const GUIDES_BY_BRAND: Record<string, Record<string, GuideArticle>> = { motolia: MOTOLIA_GUIDES };

export function getGuideArticle(brand: string, path: string): GuideArticle | undefined {
    const guides = GUIDES_BY_BRAND[brand];
    return guides && Object.prototype.hasOwnProperty.call(guides, path) ? guides[path] : undefined;
}

export function listGuidePaths(brand: string): string[] {
    return Object.keys(GUIDES_BY_BRAND[brand] ?? {});
}
